/* Bluff Show — the question bank.
   Each question is a strange-but-true fact with the answer blanked out as ____.
     cat     the category shown on screen (must match a name in CATS in app.js)
     q       the question, with ____ exactly once
     a       the true answer, short
     alts    other ways of writing the true answer, so nobody can enter it as a lie
     decoys  three believable fake answers: "Need an idea?" hints, and fillers
             when there are too few lies on the board
     fact    one sentence shown after the truth is revealed
     source  where the fact was checked
   To add a question, copy a line, change it, and keep the comma at the end. */
const QUESTIONS = [
  {"cat":"Animals","q":"Wombats are the only animals known to do poos shaped like ____.","a":"cubes","alts":["cube","a cube","dice","squares","blocks","bricks","cube shapes"],"decoys":["pyramids","stars","rings"],"fact":"Stretchy grooves in a wombat's intestines shape its droppings into cubes, which stay put when used to mark territory.","source":"https://www.nationalgeographic.com/animals/article/wombat-poop-cube-why-is-it-square-shaped"},
  {"cat":"Animals","q":"Koalas have fingerprints so similar to ____ that they are hard to tell apart even under a microscope.","a":"humans'","alts":["humans","human","a human's","people's","people","ours","human fingerprints"],"decoys":["pandas'","kangaroos'","sloths'"],"fact":"Koalas evolved fingerprints independently, and their loops and whorls look almost identical to human prints.","source":"https://www.pbs.org/wgbh/nova/article/koala-fingerprints/"},
  {"cat":"Animals","q":"Butterflies can taste things using their ____.","a":"feet","alts":["foot","legs","their feet"],"decoys":["eyes","bellies","scales"],"fact":"Butterflies have taste sensors on their feet, and females use them to check a plant is safe before laying eggs.","source":"https://www.amnh.org/exhibitions/butterflies/butterfly-faq"},
  {"cat":"Animals","q":"A baby puffin is called a ____.","a":"puffling","alts":["a puffling","pufflings"],"decoys":["puffkin","pufflet","puffball"],"fact":"Baby puffins are called pufflings, and they stay hidden in underground burrows until they are ready to fly.","source":"https://www.pbs.org/wnet/nature/an-iceland-community-rallies-to-save-lost-baby-puffins-wild-hope/33243/"},
  {"cat":"Animals","q":"The official national animal of Scotland is the ____.","a":"unicorn","alts":["a unicorn","the unicorn","unicorns"],"decoys":["red deer","golden eagle","Highland cow"],"fact":"Scotland's national animal is the mythical unicorn, a symbol of purity and strength on its royal coat of arms since the 1500s.","source":"https://www.nts.org.uk/stories/the-unicorn-scotlands-national-animal"},
  {"cat":"Animals","q":"Hippos ooze a red liquid from their skin that works as a natural ____.","a":"sunscreen","alts":["sun cream","suncream","sun block","sunblock","sun screen"],"decoys":["perfume","glue","war paint"],"fact":"Hippo 'blood sweat' contains red and orange pigments that absorb sunlight and also kill bacteria.","source":"https://www.nature.com/articles/429363a"},
  {"cat":"Animals","q":"Underneath its fur, a polar bear's skin is ____.","a":"black","alts":["jet black","dark","dark black"],"decoys":["pink","blue","spotted"],"fact":"Polar bears have black skin to soak up heat, and their fur is actually transparent, only looking white.","source":"https://polarbearsinternational.org/news-media/articles/why-polar-bears-have-black-skin/"},
  {"cat":"Animals","q":"Adélie penguins build their nests out of ____, and often steal them from the neighbours.","a":"pebbles","alts":["pebble","stones","stone","rocks","small stones"],"decoys":["feathers","seaweed","bones"],"fact":"Pebble nests keep Adélie eggs above meltwater, and males happily pinch stones from nearby nests.","source":"https://www.discoverwildlife.com/animal-facts/birds/why-do-penguins-give-stones-to-each-other"},
  {"cat":"Animals","q":"Each bottlenose dolphin develops its own signature whistle that works like a ____.","a":"name","alts":["a name","their name","names"],"decoys":["password","lullaby","handshake"],"fact":"Dolphins use unique signature whistles as names, and they respond when another dolphin copies theirs.","source":"https://www.nationalgeographic.com/animals/article/130722-dolphins-whistle-names-identity-animals-science"},
  {"cat":"Animals","q":"Instead of blood, sea stars pump ____ around their bodies.","a":"seawater","alts":["sea water","salt water","saltwater","water"],"decoys":["air","slime","sand"],"fact":"Sea stars have no blood; a water vascular system moves seawater around to carry nutrients and work their tube feet.","source":"https://oceanservice.noaa.gov/facts/starfish.html"},
  {"cat":"Animals","q":"Rats are physically unable to ____.","a":"vomit","alts":["be sick","throw up","puke","sick up"],"decoys":["swim","sneeze","yawn"],"fact":"Rats and other rodents cannot vomit, mainly because their brainstem lacks the circuit that triggers it.","source":"https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0060537"},
  {"cat":"Animals","q":"Male platypuses have venomous spurs on their ____.","a":"ankles","alts":["ankle","back legs","hind legs","feet","heels","back feet"],"decoys":["tails","bills","elbows"],"fact":"Male platypuses have venom spurs on their back ankles, and a sting is not deadly but extremely painful.","source":"https://australian.museum/learn/animals/mammals/platypus/"},
  {"cat":"Animals","q":"Crows can remember a person's ____ for years and teach other crows to scold them.","a":"face","alts":["faces","a face","their face"],"decoys":["handwriting","shoe size","ringtone"],"fact":"University of Washington crows mobbed a 'dangerous' face mask years later, and crows that never saw the trapping joined in.","source":"https://www.washington.edu/news/2012/09/10/crows-react-to-threats-in-human-like-way/"},
  {"cat":"Animals","q":"Adult elephants are physically unable to ____.","a":"jump","alts":["leap","jump up"],"decoys":["swim","lie down","kneel"],"fact":"Elephants cannot jump: their heavy bodies, downward-pointing leg bones and stiff ankles give them no spring.","source":"https://www.livescience.com/54606-why-elephants-cannot-jump.html"},
  {"cat":"Animals","q":"Tiny tardigrades are nicknamed water bears and moss ____.","a":"piglets","alts":["piglet","pigs","piggies"],"decoys":["puppies","kittens","mice"],"fact":"Tardigrades are called water bears and moss piglets for their chubby shape and slow, lumbering walk.","source":"https://www.nationalgeographic.com/animals/invertebrates/facts/tardigrades-water-bears"},
  {"cat":"Animals","q":"When threatened by coyotes, some horned lizards squirt blood from their ____.","a":"eyes","alts":["eye","eye sockets","eyeballs"],"decoys":["nostrils","ears","armpits"],"fact":"Horned lizards burst tiny vessels near their eyes to spray foul-tasting blood that puts off dogs and foxes.","source":"https://www.nationalgeographic.com/animals/article/animals-lizards-reptiles-blood-eyes"},
  {"cat":"Animals","q":"Hummingbirds can hover in mid-air and even fly ____.","a":"backwards","alts":["backward","in reverse","back"],"decoys":["in their sleep","with one wing","underwater"],"fact":"By twisting their wings in a figure-of-eight, hummingbirds can hover and fly backwards, which few birds can manage.","source":"https://www.smithsonianmag.com/smart-news/watch-how-hummingbirds-fly-through-narrow-spaces-180983248/"},
  {"cat":"Animals","q":"In the dark Arctic winter, reindeer eyes change colour from gold to ____.","a":"blue","alts":["deep blue","dark blue"],"decoys":["red","green","purple"],"fact":"A reflective layer in reindeer eyes turns from gold in summer to blue in winter, making them far more sensitive to dim light.","source":"https://www.ucl.ac.uk/news/2013/oct/reindeers-eyes-change-colour-arctic-seasons"},
  {"cat":"Animals","q":"Australia's Fitzroy River turtle can breathe underwater through its ____.","a":"bum","alts":["bottom","butt","backside","rear","cloaca","behind","bum hole"],"decoys":["shell","armpits","eyelids"],"fact":"The 'bum-breathing turtle' absorbs oxygen through gill-like structures in its cloaca, staying underwater for long stretches.","source":"https://www.greeningaustralia.org.au/protecting-the-bum-breathing-turtles-of-the-fitzroy-river/"},
  {"cat":"Animals","q":"Every winter, the wood frog survives by letting its body ____.","a":"freeze solid","alts":["freeze","frozen","turn to ice","freeze over"],"decoys":["dry out completely","shrink in half","turn to jelly"],"fact":"Wood frogs freeze solid, heart and breathing stopped, protected by natural antifreeze, then thaw and hop off in spring.","source":"https://www.nationalgeographic.com/animals/article/animals-freeze-then-thaw-explained"},
  {"cat":"Animals","q":"Sharks have been around for longer than ____.","a":"trees","alts":["tree","the trees"],"decoys":["the Moon","mosses","sponges"],"fact":"The oldest shark fossils are about 450 million years old, while the first trees appeared tens of millions of years later.","source":"https://www.smithsonianmag.com/smart-news/respect-sharks-are-older-than-trees-3818/"},
  {"cat":"Animals","q":"An owl's eyes are not balls but are shaped like ____.","a":"tubes","alts":["tube","cylinders","cylinder","rods"],"decoys":["cones","eggs","saucers"],"fact":"Owl eyes are long tubes fixed in place by bone, so owls must turn their heads to look around.","source":"https://www.mcgill.ca/oss/article/did-you-know/owls-dont-have-eyeballs"},
  {"cat":"Animals","q":"So they don't drift away while napping, sea otters wrap themselves in ____.","a":"kelp","alts":["seaweed","kelp fronds","giant kelp"],"decoys":["fishing nets","each other's tails","driftwood"],"fact":"Sea otters anchor themselves in kelp fronds while they rest so the current doesn't carry them off.","source":"https://www.montereybayaquarium.org/animals-the-ocean/animals-a-to-z/giant-kelp"},
  {"cat":"Animals","q":"Unlike lions and tigers, cheetahs cannot ____.","a":"roar","alts":["roar at all"],"decoys":["purr","climb trees","swim"],"fact":"Cheetahs can't roar, but they purr, hiss, growl and make a bird-like chirp that is their most common call.","source":"https://nationalzoo.si.edu/animals/news/why-do-cheetahs-have-spots-and-other-cheetah-facts"},
  {"cat":"Animals","q":"An octopus has ____ hearts.","a":"three","alts":["3"],"decoys":["two","five","eight"],"fact":"Octopuses have three hearts: two pump blood through the gills and one pumps it round the body.","source":"https://www.smithsonianmag.com/science-nature/ten-wild-facts-about-octopuses-they-have-three-hearts-big-brains-and-blue-blood-7625828/"},
  {"cat":"Animals","q":"To impress females, male satin bowerbirds collect objects that are ____.","a":"blue","alts":["coloured blue","blue coloured","all blue","blue things"],"decoys":["red","yellow","heart-shaped"],"fact":"Male satin bowerbirds decorate their bowers with blue feathers, berries and even bottle caps and pen lids.","source":"https://australian.museum/learn/animals/birds/satin-bowerbird/"},
  {"cat":"History","q":"The shortest war in recorded history, lasting under an hour in 1896, was fought between Britain and ____.","a":"Zanzibar","alts":["the sultanate of zanzibar","sultanate of zanzibar"],"decoys":["Tonga","Monaco","Portugal"],"fact":"The Anglo-Zanzibar War of 27 August 1896 ended in about 40 minutes after British ships shelled the sultan's palace.","source":"https://www.britannica.com/event/Anglo-Zanzibar-War"},
  {"cat":"History","q":"To refill the treasury, Roman Emperor Vespasian put a tax on ____.","a":"Urine","alts":["pee","human urine","urine collected from public toilets"],"decoys":["Sandals","Pet cats","Olive pits"],"fact":"Urine from public toilets was sold to launderers and tanners for its ammonia, so Vespasian taxed it.","source":"https://blog.education.nationalgeographic.org/2016/04/15/urine-trouble-taxes-in-ancient-rome/"},
  {"cat":"History","q":"In 1932, Australian soldiers armed with machine guns were sent to fight a 'war' against ____.","a":"Emus","alts":["emu","the emus"],"decoys":["Kangaroos","Rabbits","Crocodiles"],"fact":"The Great Emu War tried to stop emus wrecking wheat farms in Western Australia, and the birds largely won.","source":"https://www.britannica.com/topic/Emu-War"},
  {"cat":"History","q":"From 1900 to 1920, ____ was an official Olympic sport.","a":"Tug of war","alts":["tug-of-war","tug o war","rope pulling"],"decoys":["Hide and seek","Sack racing","Leapfrog"],"fact":"Tug of war featured at five Olympic Games; Britain's police team won gold at its final appearance in 1920.","source":"https://www.olympics.com/en/news/antwerp-1920-tug-of-war-and-a-72-year-old-medallist"},
  {"cat":"History","q":"In the 1830s, an Ohio doctor sold ____ in pill form as a cure for indigestion.","a":"Ketchup","alts":["tomato ketchup","catsup","tomato sauce"],"decoys":["Peanut butter","Popcorn","Maple syrup"],"fact":"Dr. John Cook Bennett promoted tomato ketchup pills as medicine in 1834, sparking a craze for 'tomato pills'.","source":"https://www.popsci.com/science/ketchup-history-medicine/"},
  {"cat":"History","q":"To make Russia look more modern, Tsar Peter the Great introduced a tax on ____.","a":"Beards","alts":["beard","facial hair","having a beard"],"decoys":["Pet parrots","Pocket watches","Snowshoes"],"fact":"From 1698, bearded men had to pay and carry a token proving it, or risk being shaved on the spot.","source":"https://www.smithsonianmag.com/smart-news/why-tsar-peter-great-established-beard-tax-180964693/"},
  {"cat":"History","q":"In 1324, the ruler of ____ handed out so much gold in Cairo that its value there dropped for years.","a":"Mali","alts":["the mali empire","mali empire"],"decoys":["Persia","Ethiopia","Oman"],"fact":"Mansa Musa of Mali passed through Cairo on pilgrimage to Mecca, and his lavish gifts pushed down gold's value.","source":"https://worldhistorycommons.org/al-umaris-account-mansa-musas-visit-cairo"},
  {"cat":"History","q":"China's Terracotta Army was discovered in 1974 by farmers who were digging a ____.","a":"Well","alts":["water well","a well"],"decoys":["Fish pond","Grave","Rice paddy"],"fact":"Farmers near Xi'an hit pottery fragments while digging a well, uncovering thousands of life-sized clay soldiers.","source":"https://www.liverpoolmuseums.org.uk/stories/top-10-facts-about-terracotta-warriors"},
  {"cat":"History","q":"The Rosetta Stone was found in 1799 by French soldiers digging foundations for a ____.","a":"Fort","alts":["fortress","a fort","fort extension"],"decoys":["Bridge","Hospital","Windmill"],"fact":"Napoleon's soldiers unearthed it while extending a fort near the Egyptian town of Rashid (Rosetta).","source":"https://www.britishmuseum.org/blog/everything-you-ever-wanted-know-about-rosetta-stone"},
  {"cat":"History","q":"Abraham Lincoln is honored in the National ____ Hall of Fame.","a":"Wrestling","alts":["wrestling hall of fame","wrestlers"],"decoys":["Axe Throwing","Fencing","Chess"],"fact":"Lincoln was a skilled frontier wrestler and was inducted as an 'Outstanding American' in 1992.","source":"https://nwhof.org/hall_of_fame/bio/128"},
  {"cat":"History","q":"Parts of the Great Wall of China were built with mortar that contained ____.","a":"Sticky rice","alts":["rice","glutinous rice","sticky rice flour","sweet rice"],"decoys":["Goat milk","Green tea","Silkworm silk"],"fact":"Chinese builders mixed sticky rice soup with lime, creating an unusually strong mortar that peaked in use under the Ming.","source":"https://www.smithsonianmag.com/history/sticky-rice-mortar-view-space-and-more-fun-facts-about-chinas-great-wall-180962197/"},
  {"cat":"History","q":"An iron dagger buried with Tutankhamun was made from a ____.","a":"Meteorite","alts":["meteor","meteoritic iron","space rock","iron meteorite"],"decoys":["Melted spearhead","Ship anchor","Chariot wheel"],"fact":"A 2016 chemical analysis found the blade's nickel and cobalt levels matched iron from a meteorite.","source":"https://onlinelibrary.wiley.com/doi/10.1111/maps.12664"},
  {"cat":"History","q":"The Aztecs used ____ as money.","a":"Cacao beans","alts":["cacao","cocoa beans","cocoa","chocolate beans","cacao seeds"],"decoys":["Painted pebbles","Llama wool","Coconut shells"],"fact":"One Aztec record valued a single cacao bean at one tamale, and 100 beans at a turkey hen.","source":"https://www.si.edu/object/cacao-beans:nmah_867620"},
  {"cat":"History","q":"From 1886 to 1902, the Statue of Liberty served as an official ____.","a":"Lighthouse","alts":["light house","navigation light","beacon"],"decoys":["Weather station","Post office","Fire lookout"],"fact":"The US Lighthouse Board ran the statue as an aid to navigation, lighting its torch with electric lamps.","source":"https://www.nps.gov/articles/000/stli-liberty-island-650003.htm"},
  {"cat":"History","q":"In 1952, Albert Einstein was offered the job of President of ____.","a":"Israel","alts":["the state of israel"],"decoys":["Switzerland","Germany","Princeton University"],"fact":"After Chaim Weizmann died, Israel offered Einstein the presidency; he declined, saying he lacked the aptitude.","source":"https://www.britannica.com/story/the-time-albert-einstein-was-asked-to-be-president-of-israel"},
  {"cat":"History","q":"When Egypt's Great Pyramid was built, ____ still lived on a remote Arctic island.","a":"Woolly mammoths","alts":["mammoths","mammoth","woolly mammoth","wooly mammoths"],"decoys":["Sabre-toothed cats","Cave bears","Giant ground sloths"],"fact":"The last woolly mammoths survived on Russia's Wrangel Island until about 4,000 years ago, after the pyramid's construction.","source":"https://www.nationalgeographic.com/science/article/woolly-mammoth-last-extinction-genetics"},
  {"cat":"History","q":"Japanese soldier Hiroo Onoda kept fighting World War II in a Philippine jungle until ____.","a":"1974","alts":["the year 1974","march 1974"],"decoys":["1951","1962","1983"],"fact":"Onoda refused to believe the war was over until his former commanding officer flew in and relieved him of duty.","source":"https://text-message.blogs.archives.gov/2023/05/25/onoda-of-the-jungle/"},
  {"cat":"History","q":"Abraham Lincoln was born on the exact same day as ____.","a":"Charles Darwin","alts":["darwin"],"decoys":["Edgar Allan Poe","Queen Victoria","Charles Dickens"],"fact":"Lincoln and Darwin were both born on 12 February 1809.","source":"https://www.britannica.com/biography/The-Darwin-Lincoln-Double-Bicentennial-2222484"},
  {"cat":"History","q":"Korean admiral Yi Sun-sin fought Japanese invaders in the 1590s using armored '____ ships'.","a":"Turtle","alts":["turtle ship","turtle ships","kobukson","geobukseon"],"decoys":["Tiger","Crab","Whale"],"fact":"The kobukson, or turtle ship, had a covered, spiked deck and may have been the first ironclad warship.","source":"https://www.britannica.com/technology/kobukson"},
  {"cat":"History","q":"The very first basketball game, in 1891, used ____ as hoops.","a":"Peach baskets","alts":["peach basket","baskets","fruit baskets"],"decoys":["Barrel hoops","Bicycle wheels","Laundry tubs"],"fact":"James Naismith nailed two peach baskets to a gym balcony ten feet up, which is why it is called basketball.","source":"https://www.hoophall.com/explore/exhibits/1891"},
  {"cat":"History","q":"The world's oldest operating university, al-Qarawiyyin in Morocco, was founded in 859 by a ____.","a":"Woman","alts":["muslim woman","fatima al-fihri","fatima al fihri","merchant's daughter","wealthy woman"],"decoys":["Camel trader","Sultan's chef","Blind poet"],"fact":"Fatima al-Fihri used her inheritance to found the mosque and school in Fez that became al-Qarawiyyin.","source":"https://www.worldhistory.org/article/2662/fatima-al-fihri-and-al-qarawiyyin-university/"},
  {"cat":"History","q":"Before rubber erasers, people rubbed out pencil marks using ____.","a":"Bread","alts":["bread crumbs","breadcrumbs","moist bread","damp bread"],"decoys":["Potato slices","Onion skins","Chalk dust"],"fact":"Balled-up damp bread was the usual eraser until rubber caught on around 1770, named for how it rubbed out marks.","source":"https://www.snopes.com/fact-check/bread-erase-pencil-marks/"},
  {"cat":"History","q":"Oxford University is older than the ____ Empire.","a":"Aztec","alts":["aztecs","aztec empire","tenochtitlan","mexica"],"decoys":["Roman","Persian","Byzantine"],"fact":"Teaching at Oxford began by 1096; the Aztec capital Tenochtitlan was founded in 1325 and the empire in 1428.","source":"https://www.smithsonianmag.com/smart-news/university-oxford-older-than-aztec-empire-other-facts-will-change-your-perspective-history-1529607/"},
  {"cat":"History","q":"Cleopatra lived closer in time to the ____ than to the building of the Great Pyramid.","a":"Moon landing","alts":["first moon landing","apollo 11","apollo moon landing","the moon landing"],"decoys":["Invention of writing","Invention of the wheel","End of the Ice Age"],"fact":"The Great Pyramid was about 2,500 years old in Cleopatra's time; the 1969 Moon landing came about 2,000 years after her.","source":"https://www.smithsonianmag.com/smart-news/university-oxford-older-than-aztec-empire-other-facts-will-change-your-perspective-history-1529607/"},
  {"cat":"History","q":"Despite its name, the Hundred Years' War between England and France lasted ____.","a":"116 years","alts":["116","one hundred sixteen years","one hundred and sixteen years"],"decoys":["81 years","99 years","132 years"],"fact":"It ran on and off from 1337 to 1453, with long truces between campaigns.","source":"https://www.history.com/articles/hundred-years-war"},
  {"cat":"History","q":"The Inca Empire kept its records using ____ instead of writing.","a":"Knotted strings","alts":["knots","knotted cords","quipu","khipu","quipus","string knots"],"decoys":["Clay tablets","Carved bones","Woven feathers"],"fact":"Inca officials recorded numbers and data in quipu, bundles of coloured cords tied with knots.","source":"https://www.si.edu/collections/snapshot/quipu"},
  {"cat":"Food","q":"In the 1830s, American pharmacies sold tomato extract in the form of ____ that claimed to cure indigestion.","a":"pills","alts":["tomato pills","capsules","tablets","pill"],"decoys":["chewing gum","lozenges shaped like tomatoes","face cream"],"fact":"'Tomato pills' became a US health craze from 1835, sold as a cure-all; later checks found some contained no tomato at all.","source":"https://www.popsci.com/science/ketchup-history-medicine/"},
  {"cat":"Food","q":"The word 'ketchup' probably comes from a Hokkien Chinese name for a sauce made from fermented ____.","a":"fish","alts":["fish sauce","fermented fish","fishes"],"decoys":["plums","chillies","rice"],"fact":"Ketchup likely comes from Hokkien 'ke-tsiap', a fermented fish sauce; tomatoes were only added centuries later.","source":"https://www.npr.org/sections/codeswitch/2013/12/02/248195661/ketchup-the-all-american-condiment-that-comes-from-asia"},
  {"cat":"Food","q":"To a botanist, a banana counts as a ____.","a":"berry","alts":["berries","a berry"],"decoys":["drupe","nut","legume"],"fact":"A banana grows from a single flower ovary with seeds inside, making it a true berry. Strawberries, oddly, are not.","source":"https://www.livescience.com/57477-why-are-bananas-considered-berries.html"},
  {"cat":"Food","q":"Peanuts aren't really nuts. Botanically they are ____.","a":"legumes","alts":["legume","a legume","beans","pulses"],"decoys":["berries","tubers","grains"],"fact":"Peanuts grow underground in pods and belong to the same plant family as beans, peas and chickpeas.","source":"https://nationalpeanutboard.org/faqs/"},
  {"cat":"Food","q":"Archaeologists have found honey that was still edible inside ancient Egyptian ____.","a":"tombs","alts":["tomb","burial tombs","graves"],"decoys":["bathhouses","clay ovens","water wells"],"fact":"Sealed honey barely spoils: it is low in water and acidic, so pots thousands of years old were found still edible.","source":"https://www.smithsonianmag.com/science-nature/the-science-behind-honeys-eternal-shelf-life-1218690/"},
  {"cat":"Food","q":"Traditional Worcestershire sauce gets its savoury kick from fermented ____.","a":"anchovies","alts":["anchovy","fish","anchovy fish"],"decoys":["mushrooms","walnuts","seaweed"],"fact":"Lea & Perrins Worcestershire sauce, first sold in 1837, is made with fermented anchovies, tamarind, vinegar and molasses.","source":"https://en.wikipedia.org/wiki/Worcestershire_sauce"},
  {"cat":"Food","q":"Fortune cookies, handed out in Chinese restaurants in America, most likely originated in ____.","a":"Japan","alts":["japanese","kyoto"],"decoys":["Mexico","Portugal","Korea"],"fact":"Researchers traced fortune cookies to Japanese 'tsujiura senbei' crackers; Japanese bakers brought them to California.","source":"https://www.history.com/articles/fortune-cookies-invented-chinese-japanese"},
  {"cat":"Food","q":"In 1667 the Dutch let England keep Manhattan, while they kept Run, a tiny island famous for ____.","a":"nutmeg","alts":["nutmegs","mace","nutmeg and mace"],"decoys":["cinnamon","black pepper","cloves"],"fact":"Under the Treaty of Breda, the Dutch kept nutmeg-rich Run in Indonesia, and New Amsterdam became English New York.","source":"https://en.wikipedia.org/wiki/Treaty_of_Breda_(1667)"},
  {"cat":"Food","q":"Most 'wasabi' served with sushi outside Japan is actually dyed ____.","a":"horseradish","alts":["horse radish","horseradish paste"],"decoys":["avocado","broccoli","spinach"],"fact":"Real wasabi is hard to grow and very perishable, so most green paste is horseradish, mustard and green colouring.","source":"https://www.britannica.com/topic/wasabi"},
  {"cat":"Food","q":"Each cashew nut grows dangling from the bottom of a fruit called the cashew ____.","a":"apple","alts":["apples","cashew apple"],"decoys":["pear","plum","bell"],"fact":"The cashew nut hangs below a juicy, pear-shaped 'cashew apple', which is eaten or made into juice in many countries.","source":"https://www.britannica.com/science/cashew-apple"},
  {"cat":"Food","q":"Signs in Singapore's MRT train stations ban passengers from bringing ____.","a":"durians","alts":["durian","durian fruit","durian fruits"],"decoys":["dried fish","blue cheese","belacan"],"fact":"Singapore's MRT banned durians in 1988 because their smell lingers in air-conditioned trains.","source":"https://mothership.sg/2025/05/singapore-ban-durians-hotels-public-transport/"},
  {"cat":"Food","q":"The world's first instant noodles, launched in Japan in 1958, came in one flavour: ____.","a":"chicken","alts":["chicken ramen","chicken flavour","chicken flavor"],"decoys":["miso","soy sauce","seafood"],"fact":"Momofuku Ando, founder of Nissin, created 'Chicken Ramen' in 1958 to help feed post-war Japan.","source":"https://www.history.com/this-day-in-history/august-25/first-instant-ramen-invented-momofuku-ando-1958"},
  {"cat":"Food","q":"The Caesar salad was invented in 1924 in the city of ____.","a":"Tijuana","alts":["tijuana, mexico","tijuana mexico","mexico"],"decoys":["Rome","Las Vegas","Monaco"],"fact":"Italian-born chef Caesar Cardini created it at his restaurant in Tijuana, Mexico, using whatever ingredients he had left.","source":"https://www.britannica.com/topic/Caesar-salad"},
  {"cat":"Food","q":"Chilli peppers make their burn to put off hungry animals, but ____ can't feel it, so they spread the seeds.","a":"birds","alts":["bird","wild birds"],"decoys":["fruit bats","goats","elephants"],"fact":"Birds' heat sensors don't respond to capsaicin, so they eat chillies happily and scatter the seeds far and wide.","source":"https://pubmed.ncbi.nlm.nih.gov/11853675/"},
  {"cat":"Food","q":"Until 1959, New Zealand sold kiwifruit under the name Chinese ____.","a":"gooseberry","alts":["gooseberries","chinese gooseberry"],"decoys":["potato","plum","fig"],"fact":"Exporters Turners & Growers renamed the fruit after New Zealand's kiwi bird to make it easier to sell overseas.","source":"https://nzhistory.govt.nz/chinese-gooseberry-becomes-kiwifruit"},
  {"cat":"Food","q":"In the earliest sushi, the rice was used to ferment the fish and was then ____.","a":"thrown away","alts":["discarded","thrown out","binned","not eaten","thrown"],"decoys":["fed to chickens","burned as fuel","used as glue"],"fact":"Early sushi was a way to preserve fish in fermenting rice; only the fish was eaten until around the 1300s-1500s.","source":"https://en.wikipedia.org/wiki/History_of_sushi"},
  {"cat":"Food","q":"The French croissant descends from the kipferl, a crescent-shaped roll from ____.","a":"Austria","alts":["vienna","austrian"],"decoys":["Belgium","Denmark","Portugal"],"fact":"An Austrian named August Zang opened a Viennese bakery in Paris in 1839, and French bakers turned the kipferl into the croissant.","source":"https://www.ice.edu/blog/brief-history-croissant"},
  {"cat":"Food","q":"The spice saffron is made from the dried ____ of a crocus flower.","a":"stigmas","alts":["stigma","threads","stigmata"],"decoys":["petals","pollen","roots"],"fact":"Each saffron crocus has just three stigmas, picked by hand; a pound of saffron takes about 75,000 flowers.","source":"https://www.britannica.com/topic/saffron"},
  {"cat":"Food","q":"Fanta was first made in 1940 in ____, when wartime blockades cut off Coca-Cola syrup.","a":"Germany","alts":["german","nazi germany"],"decoys":["Brazil","Spain","Mexico"],"fact":"Coca-Cola's German boss Max Keith made Fanta from leftovers like whey and apple pulp when Coke syrup couldn't be imported.","source":"https://www.snopes.com/fact-check/the-reich-stuff/"},
  {"cat":"Food","q":"Bird's nest soup is made from nests that swiftlets build almost entirely out of their own ____.","a":"saliva","alts":["spit","drool","spittle"],"decoys":["feathers","eggshells","tree sap"],"fact":"Edible-nest swiftlets of Southeast Asia glue their nests together from hardened saliva, which is harvested for soup.","source":"https://www.britannica.com/animal/swiftlet"},
  {"cat":"Food","q":"Kopi luwak is a pricey coffee made from beans that have passed through the gut of a ____.","a":"civet","alts":["palm civet","asian palm civet","civet cat","luwak","civets"],"decoys":["sun bear","pangolin","tapir"],"fact":"Asian palm civets eat coffee cherries; the beans are collected from their droppings, washed and roasted.","source":"https://www.britannica.com/topic/Kopi-Luwak"},
  {"cat":"Food","q":"Sriracha chilli sauce is named after a seaside town in ____.","a":"Thailand","alts":["thai","si racha","chonburi"],"decoys":["Vietnam","Indonesia","Sri Lanka"],"fact":"The sauce is named after Si Racha in Chonburi province, Thailand, where a local family began bottling it in the 1930s.","source":"https://en.wikipedia.org/wiki/Si_Racha"},
  {"cat":"Food","q":"Tempura was brought to Japan in the 1500s by missionaries and traders from ____.","a":"Portugal","alts":["portuguese","the portuguese"],"decoys":["the Netherlands","China","India"],"fact":"Portuguese visitors introduced flour-battered frying; the name may come from 'tempora', Catholic fasting days.","source":"https://guide.michelin.com/hk/en/article/features/tempura_en"},
  {"cat":"Food","q":"The Aztecs used cacao beans not only to make drinks but also as ____.","a":"money","alts":["currency","cash","coins","payment"],"decoys":["fishing bait","roof tiles","dice"],"fact":"Cacao beans were everyday currency in Aztec markets, valuable enough that people made counterfeit beans.","source":"https://www.britannica.com/topic/cocoa-bean"},
  {"cat":"Food","q":"When the chemist who invented a famous tube-shaped snack can died in 2008, some of his ashes were buried in ____.","a":"a Pringles can","alts":["pringles can","a pringles tube","pringles tube","pringles","pringles container","a pringles container"],"decoys":["a potato field","the Pringles factory","a giant crisp packet"],"fact":"Fredric Baur, who patented the Pringles tube, died in 2008; his family buried part of his ashes in an Original flavour can.","source":"https://www.npr.org/2008/06/03/91098067/inventors-ashes-buried-in-his-creation-pringles-can"},
  {"cat":"Weird Laws","q":"Since 1992, it has been illegal to sell ordinary ____ in Singapore.","a":"chewing gum","alts":["gum","chewing-gum","bubble gum","bubblegum"],"decoys":["yo-yos","pineapple pizza","rubber ducks"],"fact":"Singapore banned selling gum in 1992 after stuck gum jammed train doors; only medical and dental gum is sold, via pharmacies.","source":"https://www.nlb.gov.sg/main/article-detail?cmsuuid=8d4408cb-eb2d-4604-921e-7fa55f51baf3"},
  {"cat":"Weird Laws","q":"Swiss animal welfare law says you are not allowed to keep a ____ on its own.","a":"guinea pig","alts":["guinea pigs","a guinea pig","cavy"],"decoys":["hamster","chameleon","corn snake"],"fact":"Guinea pigs are social animals, so Swiss law requires them to be kept in groups of at least two.","source":"https://www.swissinfo.ch/eng/culture/loo-flushing-explosives-gold_fact-check-lonely-guinea-pigs-and-other-quirky-swiss-rumours/45067078"},
  {"cat":"Weird Laws","q":"Under Japan's 2008 'Metabo law', adults aged 40 to 74 get their ____ measured at yearly health checks.","a":"waistline","alts":["waist","waists","waistlines","waist size","waist measurement","waist circumference"],"decoys":["shoe size","neck size","hair length"],"fact":"The law targets metabolic syndrome: people over the waist limits are offered diet and exercise counselling, not punished.","source":"https://www.snopes.com/fact-check/the-metabo-law/"},
  {"cat":"Weird Laws","q":"Since 2008, Venice has fined people for feeding the ____.","a":"pigeons","alts":["pigeon","the pigeons","birds"],"decoys":["gondoliers","canal eels","stone lions"],"fact":"Venice banned pigeon feeding in 2008 to protect its monuments, putting St Mark's Square birdseed sellers out of business.","source":"https://www.nbcnews.com/id/wbna24390018"},
  {"cat":"Weird Laws","q":"Since 2019, tourists in Rome can be fined up to 400 euros for ____ on the Spanish Steps.","a":"sitting","alts":["sitting down","sit","sitting on them","sitting on the steps"],"decoys":["whistling","walking backwards","taking selfies"],"fact":"After a costly restoration, Rome banned sitting, eating and drinking on the Spanish Steps, with police patrolling them.","source":"https://www.abc.net.au/news/2019-08-08/spanish-steps-rome-tourist-sitting-ban-enforced-by-police-fines/11396150"},
  {"cat":"Weird Laws","q":"In Finland, fines for serious speeding are calculated from the driver's ____.","a":"income","alts":["salary","wages","earnings","daily income","pay","wealth"],"decoys":["age","engine size","years of driving"],"fact":"Finland's 'day fines' are based on disposable income, so rich speeders have received tickets topping 100,000 euros.","source":"https://www.euronews.com/2023/01/04/finlands-progressive-punishment-when-it-comes-to-speeding-tickets"},
  {"cat":"Weird Laws","q":"Hikers on the trails of Italy's Cinque Terre can be fined up to 2,500 euros for wearing ____.","a":"flip-flops","alts":["flip flops","flipflops","sandals","thongs","open sandals"],"decoys":["headphones","backpacks","sunglasses"],"fact":"Since 2019 the park has fined hikers in flip-flops or sandals, after rescuers kept being called out for slips.","source":"https://travel.yahoo.com/advice/safety/articles/cinque-terre-national-park-bans-183048046.html"},
  {"cat":"Weird Laws","q":"Denmark keeps an official government list of approved ____, and anything not on it needs special permission.","a":"baby names","alts":["names","first names","children's names","baby name","given names"],"decoys":["birthday songs","bread recipes","sandwich toppings"],"fact":"Danish parents choose from a list of over 45,000 approved names; new names must be approved before use.","source":"https://www.thelocal.dk/20220725/explained-the-rules-for-naming-a-baby-in-denmark"},
  {"cat":"Weird Laws","q":"New Jersey is the only US state where drivers are not allowed to ____.","a":"pump their own gas","alts":["pump gas","pump own gas","pump their gas","fill their own tank","fuel their own car","self-serve gas","pump your own gas"],"decoys":["drive barefoot","eat while driving","wear sandals"],"fact":"Oregon lifted its self-serve ban in 2023, leaving New Jersey as the last state where attendants must pump your gas.","source":"https://www.nbcnews.com/politics/politics-news/oregon-lifts-ban-self-serve-gas-leaving-nj-only-state-prohibiting-rcna98260"},
  {"cat":"Weird Laws","q":"Under a 1986 UK law, it is an offence to handle a ____ in suspicious circumstances.","a":"salmon","alts":["salmons","a salmon","sea trout","fish"],"decoys":["lobster","pineapple","garden gnome"],"fact":"Section 32 of the Salmon Act 1986 targets people dealing in fish they suspect was caught illegally.","source":"https://www.legislation.gov.uk/ukpga/1986/62/section/32"},
  {"cat":"Weird Laws","q":"Under an 1839 law still in force, flying a ____ to the annoyance of others is an offence on London's streets.","a":"kite","alts":["kites"],"decoys":["flag","paper plane","pigeon"],"fact":"The Metropolitan Police Act 1839 still lists flying 'any kite' to annoy residents or passers-by as a street nuisance.","source":"https://www.legislation.gov.uk/ukpga/Vict/2-3/47/section/54"},
  {"cat":"Weird Laws","q":"Iceland banned ____ for 74 years, until 1 March 1989.","a":"beer","alts":["strong beer","beers","lager"],"decoys":["jeans","pizza","electric guitars"],"fact":"Other alcohol was legalised decades earlier, but beer stayed banned until 1989; Icelanders now celebrate 1 March as Beer Day.","source":"https://learningenglish.voanews.com/a/happy-beer-day-iceland-marks-30th-anniversary-of-end-of-ban/4809730.html"},
  {"cat":"Weird Laws","q":"Since 2017, French law gives workers a 'right to disconnect' from ____ outside working hours.","a":"work emails","alts":["emails","email","work email","work e-mails","e-mails","office email"],"decoys":["social media","Wi-Fi","television"],"fact":"French companies with over 50 staff must agree rules so employees are not expected to answer work emails off the clock.","source":"https://www.loc.gov/item/global-legal-monitor/2017-01-13/france-right-to-disconnect-takes-effect/"},
  {"cat":"Weird Laws","q":"Norway's Arctic islands of Svalbard do not allow people to keep pet ____.","a":"cats","alts":["cat","house cats","kittens"],"decoys":["parrots","rabbits","hamsters"],"fact":"Cats have been banned on Svalbard since 1992 to protect wild birds and limit disease risks such as rabies.","source":"https://www.snopes.com/fact-check/cats-banned-longyearbyen-norway/"},
  {"cat":"Weird Laws","q":"In Denmark, friends cover someone who is still single on their 25th birthday in ____.","a":"cinnamon","alts":["ground cinnamon","cinnamon powder"],"decoys":["glitter","mustard","confetti"],"fact":"Unmarried 25-year-olds get a cinnamon shower; still single at 30, they get pepper instead, a nod to old spice-trade bachelors.","source":"https://www.thelocal.dk/20220218/why-do-danes-cover-each-other-in-cinnamon-on-their-25th-birthdays"},
  {"cat":"Weird Laws","q":"Every Christmas Eve at 3pm, millions of Swedes sit down to watch ____ on TV.","a":"Donald Duck","alts":["donald duck cartoons","kalle anka","donald duck and friends","disney cartoons","disney"],"decoys":["The Sound of Music","Mr Bean","Pingu"],"fact":"Since 1959 Swedish TV has shown the same Disney special, 'Donald Duck and His Friends Wish You a Merry Christmas', every Christmas Eve.","source":"https://www.atlasobscura.com/articles/sweden-christmas-donald-duck-television"},
  {"cat":"Weird Laws","q":"In Japan, a hugely popular Christmas tradition is eating ____.","a":"KFC","alts":["kentucky fried chicken","fried chicken","kfc chicken","kentucky"],"decoys":["hot dogs","instant ramen","spaghetti"],"fact":"A 1974 'Kentucky for Christmas' ad campaign made KFC buckets a Japanese Christmas staple, often ordered weeks ahead.","source":"https://fortune.com/2016/12/19/japan-christmas-celebration-kfc/"},
  {"cat":"Weird Laws","q":"At a festival in a Spanish village, men dressed as devils leap over ____.","a":"babies","alts":["baby","newborns","newborn babies","infants"],"decoys":["sheep","pumpkins","sleeping dogs"],"fact":"At El Colacho in Castrillo de Murcia, held since 1620, 'devils' jump over babies on mattresses to ward off evil.","source":"https://www.nationalgeographic.com/culture/article/el-colacho-baby-jumping-festival-murcia-spain"},
  {"cat":"Weird Laws","q":"Every spring, racers throw themselves down Cooper's Hill in England chasing a rolling ____.","a":"cheese","alts":["wheel of cheese","cheese wheel","double gloucester","round of cheese","a cheese"],"decoys":["barrel","pumpkin","tractor tyre"],"fact":"Racers chase a 3-4 kg Double Gloucester cheese down a hill so steep that the cheese is almost never caught.","source":"https://en.wikipedia.org/wiki/Cooper's_Hill_Cheese-Rolling_and_Wake"},
  {"cat":"Weird Laws","q":"Finland hosts a world championship race where competitors carry their ____ through an obstacle course.","a":"wives","alts":["wife","partner","partners","spouse","spouses"],"decoys":["grandmas","reindeer","fridges"],"fact":"The Wife Carrying World Championships in Sonkajärvi have a water pit, and winners have been rewarded with the wife's weight in beer.","source":"https://www.nbcnews.com/pop-culture/pop-culture-news/finnish-couple-wins-wife-carrying-world-championship-n148896"},
  {"cat":"Weird Laws","q":"In South Korea, it is traditional to eat ____ on your birthday.","a":"seaweed soup","alts":["miyeokguk","miyeok-guk","miyeok guk","seaweed","birthday soup"],"decoys":["raw octopus","spicy crab","pumpkin porridge"],"fact":"Miyeokguk is served to new mothers after birth, so eating it on birthdays honours your mother.","source":"https://www.korea.net/NewsFocus/HonoraryReporters/view?articleId=190103"},
  {"cat":"Weird Laws","q":"Every 23 December, artists in Oaxaca, Mexico, compete by carving giant ____.","a":"radishes","alts":["radish","giant radishes"],"decoys":["pumpkins","watermelons","blocks of ice"],"fact":"The Night of the Radishes began as a market gimmick; an official contest has run since 1897.","source":"https://www.smithsonianmag.com/travel/why-radish-carving-has-become-popular-holiday-event-oaxaca-180971096/"},
  {"cat":"Weird Laws","q":"The Norwegian King's Guard's mascot, who was knighted in 2008, is a ____.","a":"penguin","alts":["king penguin","penguins","a penguin"],"decoys":["reindeer","moose","goat"],"fact":"Sir Nils Olav, a king penguin at Edinburgh Zoo, was knighted in 2008 and has since been promoted to major general.","source":"https://www.nbcnews.com/news/amp/wbna26219632"},
  {"cat":"Weird Laws","q":"In the Welsh winter custom of Mari Lwyd, singers go door to door carrying a decorated ____ on a pole.","a":"horse skull","alts":["horse's skull","skull","horse head","horse's head","horse skull on a pole"],"decoys":["giant leek","dragon puppet","sheep's fleece"],"fact":"The Mari Lwyd, or 'grey mare', is a horse skull draped in a sheet and ribbons whose jaws snap as it seeks entry.","source":"https://www.horniman.ac.uk/story/the-mystery-of-mari-lwyd/"},
  {"cat":"Weird Laws","q":"Every summer, a royal team rows up the River Thames to count and check the ____.","a":"swans","alts":["swan","mute swans","cygnets","the king's swans","royal swans"],"decoys":["ducks","bridges","otters"],"fact":"During Swan Upping, the monarch's Swan Marker counts and checks cygnets; the Crown can claim any unmarked mute swan in open water.","source":"https://www.royal.uk/swans"},
  {"cat":"Malaysia","q":"The Bornean pitcher plant Nepenthes lowii gets much of its nutrition from tree shrew ____.","a":"droppings","alts":["poop","poo","dung","faeces","feces","excrement","droppings"],"decoys":["saliva","fur","leftover fruit"],"fact":"Mountain tree shrews lick nectar from its lid and defecate into the pitcher, feeding the plant nitrogen.","source":"https://www.discoverwildlife.com/plant-facts/nepenthes-lowii"},
  {"cat":"Malaysia","q":"Botanist Henry Ridley pushed rubber planting in Malaya so hard that he was nicknamed '____ Ridley'.","a":"Mad","alts":["mad","rubber","mad ridley","rubber ridley"],"decoys":["Sticky","Seedy","Tapper"],"fact":"Planters called him 'Mad Ridley' (and 'Rubber Ridley'), but by 1920 Malaya produced over half the world's rubber.","source":"https://www.nparks.gov.sg/sbg/about/our-history/1888-ridley-and-the-malayan-rubber-industry-from-1896"},
  {"cat":"Malaysia","q":"Ocean explorer Jacques Cousteau called Sipadan Island 'an untouched piece of ____'.","a":"art","alts":["art","artwork"],"decoys":["paradise","heaven","magic"],"fact":"Cousteau said it in his 1989 film Borneo: The Ghost of the Sea Turtle.","source":"https://en.wikipedia.org/wiki/Sipadan"},
  {"cat":"Malaysia","q":"The sculptor of Kuala Lumpur's National Monument (Tugu Negara) also created America's famous ____ Memorial.","a":"Iwo Jima","alts":["iwo jima","marine corps war memorial","marine corps","us marine corps war memorial"],"decoys":["Lincoln","Vietnam Veterans","Pearl Harbor"],"fact":"Tunku Abdul Rahman admired Felix de Weldon's Iwo Jima Memorial and asked him to sculpt Tugu Negara.","source":"https://en.wikipedia.org/wiki/National_Monument_(Malaysia)"},
  {"cat":"Malaysia","q":"Before flying to space in 2007, Malaysia's first astronaut, surgeon Sheikh Muszaphar Shukor, also worked part-time as a ____.","a":"model","alts":["model","fashion model"],"decoys":["radio DJ","chef","magician"],"fact":"The orthopaedic surgeon was also a part-time model before reaching the International Space Station.","source":"https://www.britannica.com/biography/Sheikh-Muszaphar-Shukor"},
  {"cat":"Malaysia","q":"The kancil, or lesser mouse-deer, is the world's smallest ____.","a":"hoofed mammal","alts":["hoofed mammal","hoofed animal","ungulate","even-toed ungulate"],"decoys":["antelope","wild pig","marsupial"],"fact":"At around 2 kg, the lesser mouse-deer is the smallest known hoofed mammal on Earth.","source":"https://en.wikipedia.org/wiki/Lesser_mouse-deer"},
  {"cat":"Malaysia","q":"The 1999 Sean Connery heist movie ____ stages its climax at the Petronas Twin Towers.","a":"Entrapment","alts":["entrapment"],"decoys":["Twin Peril","Midnight Vault","Skybridge"],"fact":"Entrapment filmed in Kuala Lumpur, though the skybridge scenes were shot on a set at Pinewood Studios.","source":"https://en.wikipedia.org/wiki/Entrapment_(film)"},
  {"cat":"Malaysia","q":"The word 'ringgit' comes from the Malay word for ____, describing the edges of old Spanish silver dollars.","a":"jagged","alts":["jagged","serrated"],"decoys":["ring","shiny","heavy"],"fact":"Spanish dollars had serrated edges, so Malays called them ringgit, meaning jagged.","source":"https://en.wiktionary.org/wiki/ringgit"},
  {"cat":"Malaysia","q":"In 2001, Malaysia's MyKad became the first ID card to store photo and fingerprint data on a built-in ____.","a":"computer chip","alts":["chip","microchip","computer chip","smart chip"],"decoys":["magnetic strip","hologram","barcode"],"fact":"Launched on 5 September 2001, MyKad made Malaysia the first country with a chip-based biometric ID card.","source":"https://en.wikipedia.org/wiki/Malaysian_identity_card"},
  {"cat":"Malaysia","q":"Before it became famous as Musang King, the D197 durian was known as 'Raja ____'.","a":"Kunyit","alts":["kunyit","raja kunyit","turmeric"],"decoys":["Emas","Harimau","Mentega"],"fact":"Raja Kunyit means 'Turmeric King', after its deep yellow flesh; it was renamed after Gua Musang.","source":"https://en.wikipedia.org/wiki/Musang_King"},
  {"cat":"Malaysia","q":"The world's largest Milo factory is in ____, Negeri Sembilan.","a":"Chembong","alts":["chembong"],"decoys":["Kuala Pilah","Port Dickson","Jelebu"],"fact":"Nestle's Chembong factory, running since 1993, became the world's largest Milo manufacturing site in 2019.","source":"https://www.nestle.com.my/media/pressreleases/nestle-establishes-worlds-largest-milo-factory-in-negerisembilan"},
  {"cat":"Malaysia","q":"The world's tallest known tropical tree, a 100.8 m yellow meranti in Sabah's Danum Valley, is named ____.","a":"Menara","alts":["menara"],"decoys":["Gergasi","Raksasa","Tiang Langit"],"fact":"Menara means 'tower' in Malay; scientists confirmed its height using drones and laser scanning.","source":"https://en.wikipedia.org/wiki/Menara_(tree)"},
  {"cat":"Malaysia","q":"Crispy kuih kapit biscuits are nicknamed '____' in English.","a":"love letters","alts":["love letters","love letter","love letter biscuits"],"decoys":["butterfly wings","paper fans","moon crisps"],"fact":"The thin rolled or folded biscuits are said to resemble folded letters, hence 'love letters'.","source":"https://asianinspirations.com.au/recipes/love-letters-kuih-kapit/"},
  {"cat":"Malaysia","q":"Johor's Iskandar Puteri is home to Asia's first ____ theme park.","a":"Legoland","alts":["legoland","lego"],"decoys":["Barbie","Minecraft","Pokemon"],"fact":"Legoland Malaysia opened in September 2012 as the first Legoland in Asia and sixth in the world.","source":"https://en.wikipedia.org/wiki/Legoland_Malaysia_Resort"},
  {"cat":"Malaysia","q":"Nasi kandar is named after the ____ that hawkers used to carry the rice and curries.","a":"shoulder pole","alts":["pole","shoulder pole","wooden pole","kandar pole","carrying pole"],"decoys":["tiffin carrier","bicycle basket","bullock cart"],"fact":"Penang hawkers balanced rice and curry containers on a wooden pole, a kandar, across their shoulders.","source":"https://en.wikipedia.org/wiki/Nasi_kandar"},
  {"cat":"Malaysia","q":"Royal Selangor holds a Guinness record for making the world's largest pewter ____.","a":"tankard","alts":["tankard","beer mug","mug"],"decoys":["vase","keris","lantern"],"fact":"Made in 1985 for its centenary, the tankard is nearly 2 m tall and weighs 1,557 kg.","source":"https://en.wikipedia.org/wiki/Royal_Selangor"},
  {"cat":"Malaysia","q":"Louis James Fraser, after whom Fraser's Hill is named, moved tin ore out of the hills using ____.","a":"mules","alts":["mules","mule","mule trains"],"decoys":["camels","bamboo rafts","rope slides"],"fact":"The Scottish tin merchant used mules, and a mule track was built to carry ore to The Gap and Kuala Kubu.","source":"https://en.wikipedia.org/wiki/Fraser's_Hill"},
  {"cat":"Malaysia","q":"Mount Kinabalu's highest peak is named after British naturalist ____, who never actually reached it.","a":"Hugh Low","alts":["hugh low","low","sir hugh low"],"decoys":["James Brooke","Alfred Wallace","Stamford Raffles"],"fact":"Hugh Low made the first recorded ascent in 1851 but called the summit reachable only by 'winged animals'.","source":"https://en.wikipedia.org/wiki/Hugh_Low"},
  {"cat":"Malaysia","q":"The very first season of the American reality show ____ was filmed on Pulau Tiga, Sabah.","a":"Survivor","alts":["survivor","survivor borneo","survivor: borneo"],"decoys":["Big Brother","The Amazing Race","Fear Factor"],"fact":"Survivor: Borneo was filmed on Pulau Tiga in 2000 and launched the long-running CBS series.","source":"https://en.wikipedia.org/wiki/Survivor:_Borneo"},
  {"cat":"Malaysia","q":"The Malaysia Airlines logo is based on a traditional Malay ____.","a":"kite","alts":["kite","wau","wau bulan","moon kite","malay kite","wau kucing"],"decoys":["keris","sampan","songket motif"],"fact":"The red logo is a stylised wau, the traditional Malay kite, symbolising flight.","source":"https://en.wikipedia.org/wiki/Wau_bulan"},
  {"cat":"Malaysia","q":"Ipoh white coffee beans are traditionally roasted in ____ instead of sugar.","a":"palm oil margarine","alts":["margarine","palm oil margarine","palm margarine"],"decoys":["coconut milk","ghee","honey"],"fact":"Beans are roasted only in palm oil margarine; the 'white' refers to the lighter roast and added milk.","source":"https://en.wikipedia.org/wiki/Ipoh_white_coffee"},
  {"cat":"Malaysia","q":"From inside Deer Cave in Mulu, the rocks at the entrance form the profile of ____.","a":"Abraham Lincoln","alts":["abraham lincoln","lincoln","president lincoln"],"decoys":["Queen Victoria","Winston Churchill","Napoleon"],"fact":"Look back at the cave mouth from the right angle and the rock outline resembles Lincoln's side profile.","source":"https://www.mulunationalpark.com/show-caves-deer-cave-langs-cave.php"},
  {"cat":"Malaysia","q":"Port Klang, Malaysia's busiest port, was called Port ____ until 1972.","a":"Swettenham","alts":["swettenham","port swettenham"],"decoys":["Victoria","Wellington","Raffles"],"fact":"Opened in 1901 as Port Swettenham, it was renamed Port Klang in July 1972.","source":"https://en.wikipedia.org/wiki/Port_Klang"},
  {"cat":"Malaysia","q":"When Francis Light took over Penang in 1786, he renamed it '____ Island'.","a":"Prince of Wales","alts":["prince of wales","prince of wales island"],"decoys":["King George","Queen Charlotte","East India"],"fact":"It honoured the heir to the British throne; the name Prince of Wales Island lasted until after 1867.","source":"https://en.wikipedia.org/wiki/Francis_Light"},
  {"cat":"Malaysia","q":"The Petronas Twin Towers were designed by Argentine-American architect ____.","a":"Cesar Pelli","alts":["cesar pelli","césar pelli","pelli"],"decoys":["Emilio Ambasz","Rafael Vinoly","Carlos Ott"],"fact":"Cesar Pelli based the floor plan on an eight-pointed star made of two interlocking squares.","source":"https://www.petronastwintowers.com.my/the-towers/design-structure/"},
  {"cat":"Science","q":"Velcro was inspired by sticky ____ that clung to its inventor's dog during a walk.","a":"burrs","alts":["burr","burdock burrs","plant burrs","burdock","seed burrs"],"decoys":["gecko feet","cat tongues","octopus suckers"],"fact":"In 1941 George de Mestral saw burdock burrs hooked onto his dog's fur and copied their tiny hooks to create Velcro.","source":"https://invention.si.edu/invention-stories/george-de-mestral-velcror-inventor"},
  {"cat":"Science","q":"Before it became a toy, Play-Doh was sold as ____.","a":"wallpaper cleaner","alts":["a wallpaper cleaner","wallpaper cleaning putty","wallpaper cleaning dough"],"decoys":["window putty","denture adhesive","bread dough"],"fact":"Kutol Products made it in the 1930s to wipe coal soot off wallpaper; it was rebranded as a children's toy in the 1950s.","source":"https://www.smithsonianmag.com/innovation/accidental-invention-play-doh-180973527/"},
  {"cat":"Science","q":"The microwave oven was invented after a radar engineer noticed a ____ had melted in his pocket.","a":"candy bar","alts":["a candy bar","chocolate bar","a chocolate bar","chocolate","candy"],"decoys":["crayon","plastic comb","wax pencil"],"fact":"Percy Spencer's snack melted near a radar magnetron in the 1940s, leading him to test popcorn and eggs and patent microwave cooking.","source":"https://www.lindahall.org/about/news/scientist-of-the-day/percy-spencer/"},
  {"cat":"Science","q":"A group of flamingos is called a ____.","a":"flamboyance","alts":["a flamboyance"],"decoys":["blush","pinkening","parade"],"fact":"A group of these showy pink birds is known as a flamboyance, though scientists usually just say flock or colony.","source":"https://animals.howstuffworks.com/birds/what-is-a-group-of-flamingos-called.htm"},
  {"cat":"Science","q":"Wombats are the only known animals that poop in the shape of ____.","a":"cubes","alts":["cube","squares","square","little cubes","bricks"],"decoys":["triangles","rings","hearts"],"fact":"Stiff and stretchy sections of a wombat's intestine shape its droppings into cubes, which don't roll away from territory markers.","source":"https://www.smithsonianmag.com/smart-news/scientists-have-solved-mystery-how-wombats-poop-cubes-180976898/"},
  {"cat":"Science","q":"Many sea otters keep a favorite ____ in a pouch of loose skin under their arm.","a":"rock","alts":["a rock","stone","a stone","pebble","favorite rock"],"decoys":["feather","bottle cap","twig"],"fact":"Sea otters store a trusty rock in their armpit pouch and use it to smash open shellfish, sometimes keeping it for years.","source":"https://www.zmescience.com/ecology/animals-ecology/sea-otters-favorite-rock/"},
  {"cat":"Science","q":"On Venus, a single day lasts longer than a ____.","a":"year","alts":["a year","venus year","whole year","full year","venusian year"],"decoys":["decade","century","human lifetime"],"fact":"Venus takes 243 Earth days to spin once but only 225 Earth days to orbit the Sun.","source":"https://science.nasa.gov/venus/venus-facts/"},
  {"cat":"Science","q":"Astronauts coming back in from spacewalks say space smells like ____.","a":"seared steak","alts":["steak","burnt steak","cooked steak","grilled steak","seared meat","fried steak"],"decoys":["burnt popcorn","fresh rain","old gym socks"],"fact":"Astronauts describe a smell on their suits after spacewalks like seared steak, hot metal and welding fumes.","source":"https://www.nasa.gov/space-science-and-astrobiology-at-ames/interesting-fact-of-the-month-current/interesting-fact-of-the-month-2021/"},
  {"cat":"Science","q":"The word 'robot' comes from a Czech word meaning ____.","a":"forced labor","alts":["forced labour","compulsory labor","compulsory labour","drudgery","hard labor","slave labor","servitude","forced work"],"decoys":["iron man","thinking machine","tin servant"],"fact":"Karel Capek's 1920 play R.U.R. coined 'robot' from the Czech robota, meaning forced labor.","source":"https://www.merriam-webster.com/dictionary/robot"},
  {"cat":"Science","q":"Bananas are very slightly ____, thanks to a natural form of potassium.","a":"radioactive","alts":["mildly radioactive","a bit radioactive"],"decoys":["magnetic","fireproof","carbonated"],"fact":"Bananas contain potassium-40, a naturally radioactive isotope, but the dose from eating one is far too tiny to matter.","source":"https://www.mcgill.ca/oss/article/you-asked/it-true-banana-radioactive"},
  {"cat":"Science","q":"When Kleenex tissues launched in 1924, they were advertised for removing ____.","a":"cold cream","alts":["makeup","make-up","face cream","makeup remover","cold cream remover"],"decoys":["shoe polish","car wax","window smudges"],"fact":"Kleenex began as a cold cream remover; only later did people start using it as a disposable handkerchief.","source":"https://www.kleenex.com/en-us/about-us/our-history"},
  {"cat":"Science","q":"The first recorded computer 'bug' in 1947 was an actual ____ stuck inside the machine.","a":"moth","alts":["a moth","dead moth","a dead moth"],"decoys":["cockroach","beetle","spider"],"fact":"Harvard Mark II operators taped the moth into their logbook as the 'first actual case of bug being found'.","source":"https://americanhistory.si.edu/collections/object/nmah_334663"},
  {"cat":"Science","q":"Koalas have ____ that look almost identical to humans'.","a":"fingerprints","alts":["fingerprint","finger prints","prints"],"decoys":["teeth","vocal cords","eyelashes"],"fact":"University of Adelaide researchers found koala fingerprints so human-like that even their fine ridge details matched ours.","source":"https://www.livescience.com/14007-koalas-human-fingerprints.html"},
  {"cat":"Science","q":"The letters in TASER come from the name of ____, the hero of a 1911 adventure book.","a":"Tom Swift","alts":["tom a. swift","tom a swift","thomas swift"],"decoys":["Buck Rogers","Captain Nemo","Nikola Tesla"],"fact":"Inventor Jack Cover named his stun gun after 'Tom Swift and His Electric Rifle', adding an A to make it pronounceable.","source":"https://www.britannica.com/topic/TASER"},
  {"cat":"Science","q":"Butterflies can taste with their ____.","a":"feet","alts":["foot","legs","leg","feet and legs"],"decoys":["eyes","ears","wing spots"],"fact":"Taste sensors on butterflies' feet let females check a leaf's chemicals before laying eggs on it.","source":"https://carleton.ca/biology/cu-faq/do-butterflies-really-taste-through-their-feet/"},
  {"cat":"Science","q":"Sharks were swimming in the oceans before the first ____ grew on land.","a":"trees","alts":["tree","forests","forest","flowers","flower"],"decoys":["mosses","algae","bacteria"],"fact":"Sharks appear in the fossil record around 450 million years ago, tens of millions of years before the first trees.","source":"https://www.nhm.ac.uk/discover/shark-evolution-a-450-million-year-timeline.html"},
  {"cat":"Science","q":"Hippos produce a reddish 'sweat' that works as a natural ____.","a":"sunscreen","alts":["sun screen","sunblock","sun block","antibiotic","sun protection"],"decoys":["perfume","toothpaste","glue"],"fact":"The red and orange pigments in hippo sweat absorb ultraviolet light and also kill bacteria.","source":"https://www.nature.com/articles/429363a"},
  {"cat":"Science","q":"Pluto was named by ____ from Oxford, England.","a":"an 11-year-old girl","alts":["11-year-old girl","11 year old girl","eleven-year-old girl","eleven year old girl","a schoolgirl","schoolgirl","a girl","girl","young girl","a child","child","venetia burney"],"decoys":["a royal astronomer","a newspaper contest winner","a chemistry professor"],"fact":"In 1930, 11-year-old Venetia Burney suggested the name Pluto, and Lowell Observatory astronomers voted for it unanimously.","source":"https://science.nasa.gov/people/venetia-burney-phair/"},
  {"cat":"Science","q":"Cotton candy's machine was co-invented by a ____.","a":"dentist","alts":["a dentist","tooth doctor"],"decoys":["circus clown","textile weaver","chemistry teacher"],"fact":"Dentist William Morrison and confectioner John C. Wharton invented the cotton candy machine in 1897 in Nashville.","source":"https://www.britannica.com/topic/How-Was-Cotton-Candy-Invented"},
  {"cat":"Science","q":"The crack of a whip is actually a tiny ____.","a":"sonic boom","alts":["sonic booms","a sonic boom","supersonic boom","breaking the sound barrier"],"decoys":["static shock","lightning spark","air bubble popping"],"fact":"A loop racing down the whip passes the speed of sound, making a miniature sonic boom.","source":"https://www.scientificamerican.com/article/true-cause-of-whips-crack/"},
  {"cat":"Science","q":"Your 'funny bone' isn't a bone at all; it's actually a ____.","a":"nerve","alts":["ulnar nerve","the ulnar nerve","a nerve"],"decoys":["tendon","ligament","blood vessel"],"fact":"That zing when you bump your elbow is your ulnar nerve being pinched against bone just under the skin.","source":"https://my.clevelandclinic.org/health/body/21664-ulnar-nerve"},
  {"cat":"Science","q":"Fredric Baur was so proud of what he designed that some of his ashes were buried in a ____.","a":"Pringles can","alts":["pringles tube","pringles container","chip can","crisps tube","pringles"],"decoys":["lava lamp","coffee thermos","Tupperware box"],"fact":"Baur designed the Pringles tube, and in 2008 his family buried part of his ashes in an Original flavor can.","source":"https://time.com/archive/6904379/the-man-buried-in-a-pringles-can/"},
  {"cat":"Science","q":"Sunsets on Mars look ____.","a":"blue","alts":["bluish","blue-tinted","blue tinted","light blue"],"decoys":["green","purple","silver"],"fact":"Fine Martian dust lets blue light through best, so NASA's Curiosity rover filmed a blue glow around the setting Sun.","source":"https://www.jpl.nasa.gov/news/nasas-curiosity-rover-views-serene-sundown-on-mars/"},
  {"cat":"Science","q":"Dalmatian puppies are born ____.","a":"completely white","alts":["white","all white","pure white","without spots","spotless","with no spots"],"decoys":["all black","with blue spots","striped"],"fact":"Dalmatian puppies are born white, and their spots only start appearing at around two weeks old.","source":"https://www.akc.org/expert-advice/lifestyle/6-things-you-didnt-know-about-the-dalmatian/"},
];
if (typeof module !== "undefined") module.exports = QUESTIONS;
